function E(id){return document.getElementById(id)}function trimS(s){return String(s==null?'':s).replace(/^\s+|\s+$/g,'')}function normDigits(s){s=String(s==null?'':s);var fa='۰۱۲۳۴۵۶۷۸۹',ar='٠١٢٣٤٥٦٧٨٩',i;for(i=0;i<10;i++){s=s.split(fa.charAt(i)).join(String(i));s=s.split(ar.charAt(i)).join(String(i))}return s}function num(v){var x=parseFloat(normDigits(v).replace(/[,٬\s]/g,''));return isNaN(x)?0:x}function faDigits(s){var d='۰۱۲۳۴۵۶۷۸۹';return String(s).replace(/[0-9]/g,function(x){return d.charAt(parseInt(x,10))})}function comma(n){var s=String(Math.round(num(n))),o='',c=0,i,neg='';if(s.charAt(0)=='-'){neg='-';s=s.substr(1)}for(i=s.length-1;i>=0;i--){o=s.charAt(i)+o;c++;if(c==3&&i>0){o=','+o;c=0}}return faDigits(neg+o)}function money(n){return comma(n)+' تومان'}function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')}function nowStamp(){var d=new Date();function p(x){return x<10?'0'+x:x}return d.getFullYear()+p(d.getMonth()+1)+p(d.getDate())+'_'+p(d.getHours())+p(d.getMinutes())}function idv(p){return p+'_'+(new Date().getTime())+'_'+Math.floor(Math.random()*100000)}function findById(a,id){var i;for(i=0;i<a.length;i++)if(a[i].id==id)return a[i];return null}function removeById(a,id){var i;for(i=0;i<a.length;i++)if(a[i].id==id){a.splice(i,1);return true}return false}function sumArray(a,fn){var t=0,i;for(i=0;i<a.length;i++)t+=num(fn(a[i]));return t}function monthOf(s){s=normDigits(s);return s.length>=7?s.substr(0,7):''}
function emptyDB(){return{version:11,vehicles:[],parts:[],receipts:[],employees:[],employeeWorks:[],employeePayments:[],expenses:[],supplierPayments:[],accounts:[],suppliers:[],partners:[],partnerWorks:[],partnerPayments:[],purchaseInvoices:[],notes:[],commonParts:defaultParts.slice(0),commonJobs:defaultJobs.slice(0),settings:{workshop:'خدمات خودرویی اتومحسنی',password:'3030'}}}
function ensureArrays(){var names=['vehicles','parts','receipts','employees','employeeWorks','employeePayments','expenses','supplierPayments','accounts','suppliers','partners','partnerWorks','partnerPayments','purchaseInvoices','notes','commonParts','commonJobs'],i,n,x,su;for(i=0;i<names.length;i++)if(!db[names[i]])db[names[i]]=(names[i]=='commonParts'?defaultParts.slice(0):(names[i]=='commonJobs'?defaultJobs.slice(0):[]));if(!db.settings)db.settings={workshop:'خدمات خودرویی اتومحسنی',password:'3030'};if(!db.settings.password)db.settings.password='3030';if(!db.settings.workshop)db.settings.workshop='خدمات خودرویی اتومحسنی';for(i=0;i<defaultParts.length;i++){n=defaultParts[i];if(db.commonParts.join('|').indexOf(n)<0)db.commonParts.push(n)}for(i=0;i<defaultJobs.length;i++){n=defaultJobs[i];if(db.commonJobs.join('|').indexOf(n)<0)db.commonJobs.push(n)}for(i=0;i<db.parts.length;i++){x=db.parts[i];if(!x.supplierId&&x.supplier){su=findSupplierByName(x.supplier);if(!su){su={id:idv('su'),name:x.supplier,phone:'',address:'',note:''};db.suppliers.push(su)}x.supplierId=su.id}if(x.sellUnitPrice==null)x.sellUnitPrice=x.unitPrice}for(i=0;i<db.employees.length;i++){x=db.employees[i];if(!x.salaryMode){if(x.settlement=='درصدی')x.salaryMode='درصدی از اجرت خودرو';else if(x.settlement=='روزمزد')x.salaryMode='روزانه';else if(x.settlement=='ثابت')x.salaryMode='هفتگی';else x.salaryMode='موردی/دستی'}if(x.salaryRate==null)x.salaryRate=0;if(x.active==null)x.active='بله'}for(i=0;i<db.employeePayments.length;i++){x=db.employeePayments[i];if(!x.payType)x.payType='حقوق / تسویه';if(x.note==null)x.note=''}for(i=0;i<db.employeeWorks.length;i++){x=db.employeeWorks[i];if(x.units==null)x.units=1;if(!x.modeSnapshot){var ee=findById(db.employees,x.employeeId);x.modeSnapshot=ee?ee.salaryMode:'موردی/دستی'}if(x.rateSnapshot==null){var er=findById(db.employees,x.employeeId);x.rateSnapshot=er?num(er.salaryRate):0}if(x.baseLabor==null)x.baseLabor=0}db.version=11}

function doLogin(){var p=normDigits(E('loginPassword').value);if(p==String(db.settings.password||'3030')){E('loginShade').style.display='none';E('loginError').innerText='';E('loginPassword').value=''}else{E('loginError').innerText='رمز واردشده صحیح نیست.';E('loginPassword').value='';try{E('loginPassword').focus()}catch(ex){}}}
function lockApp(){E('loginShade').style.display='block';E('loginPassword').value='';E('loginError').innerText='';try{E('loginPassword').focus()}catch(ex){}}
function changePassword(){var oldp=normDigits(E('oldPass').value),np=normDigits(E('newPass').value),rp=normDigits(E('repeatPass').value);if(oldp!=String(db.settings.password||'3030')){alert('رمز فعلی اشتباه است.');return}if(np.length<4){alert('رمز جدید حداقل ۴ رقم/کاراکتر باشد.');return}if(np!=rp){alert('تکرار رمز جدید یکسان نیست.');return}db.settings.password=np;if(saveDB(true)){E('oldPass').value='';E('newPass').value='';E('repeatPass').value='';alert('رمز ورود تغییر کرد.')}}
function validateDB(x){return !!(x&&typeof x=='object'&&x.vehicles&&typeof x.vehicles.length=='number')}
function uid(p){var s,ok,i;do{s=p+'-'+Math.floor(100000+Math.random()*900000);ok=true;for(i=0;i<db.vehicles.length;i++)if(db.vehicles[i].code==s)ok=false;for(i=0;i<db.employees.length;i++)if(db.employees[i].code==s)ok=false}while(!ok);return s}function findSupplierByName(n){var i;n=trimS(n);for(i=0;i<db.suppliers.length;i++)if(trimS(db.suppliers[i].name)==n)return db.suppliers[i];return null}function supplierName(id){var s=findById(db.suppliers,id);return s?esc(s.name):'—'}function partnerName(id){var p=findById(db.partners,id);return p?esc(p.name):'—'}function accountName(id){var a=findById(db.accounts,id);return a?esc(a.name):'—'}function employeeLabel(id){var e=findById(db.employees,id);return e?esc(e.code)+' | '+esc(e.name):'—'}function vehicleLabel(id){var v=findById(db.vehicles,id);return v?esc(v.code)+' | '+esc(v.customer)+' | '+plateText(v):'—'}
function badge(s){var c='bGray';if(s=='تحویل شده'||s=='وصول شد'||s=='تسویه شده')c='bOk';else if(s=='در انتظار'||s=='در حال کار'||s=='آماده تحویل'||s=='نزدیک سررسید'||s=='واگذار شد')c='bWarn';else if(s=='برگشت خورد'||s=='لغو شده'||s=='سررسید گذشته'||s=='مانده دارد')c='bBad';return'<span class="badge '+c+'">'+esc(s||'—')+'</span>'}
function vehicleOptions(sel){var h='<option value="">انتخاب پرونده</option>',i,v;for(i=0;i<db.vehicles.length;i++){v=db.vehicles[i];h+='<option value="'+esc(v.id)+'" '+(v.id==sel?'selected="selected"':'')+'>'+esc(v.code)+' | '+esc(v.customer)+' | '+plateText(v)+'</option>'}return h}function employeeOptions(sel){var h='<option value="">انتخاب پرسنل</option>',i,x;for(i=0;i<db.employees.length;i++){x=db.employees[i];h+='<option value="'+x.id+'" '+(x.id==sel?'selected="selected"':'')+'>'+esc(x.code)+' | '+esc(x.name)+'</option>'}return h}function accountOptions(sel){var h='<option value="">انتخاب حساب</option>',i,x;for(i=0;i<db.accounts.length;i++){x=db.accounts[i];h+='<option value="'+x.id+'" '+(x.id==sel?'selected="selected"':'')+'>'+esc(x.name)+'</option>'}return h}function supplierOptions(sel){var h='<option value="">انتخاب لوازم‌فروش</option>',i,x;for(i=0;i<db.suppliers.length;i++){x=db.suppliers[i];h+='<option value="'+x.id+'" '+(x.id==sel?'selected="selected"':'')+'>'+esc(x.name)+'</option>'}return h}function partnerOptions(sel){var h='<option value="">انتخاب همکار</option>',i,x;for(i=0;i<db.partners.length;i++){x=db.partners[i];h+='<option value="'+x.id+'" '+(x.id==sel?'selected="selected"':'')+'>'+esc(x.type)+' | '+esc(x.name)+'</option>'}return h}
function vehicleStats(v){var partBuy=0,partCharge=0,supPaid=0,direct=0,emp=0,pCost=0,pCharge=0,pPaid=0,rec=0,real=0,pcheck=0,i,x;for(i=0;i<db.parts.length;i++){x=db.parts[i];if(x.vehicleId==v.id){partBuy+=num(x.qty)*num(x.unitPrice);partCharge+=num(x.qty)*num(x.sellUnitPrice==null?x.unitPrice:x.sellUnitPrice);supPaid+=num(x.paidInitial)+num(x.customerDirect);direct+=num(x.customerDirect)}}for(i=0;i<db.supplierPayments.length;i++){x=db.supplierPayments[i];if(x.vehicleId==v.id)supPaid+=num(x.amount)}for(i=0;i<db.employeeWorks.length;i++){x=db.employeeWorks[i];if(x.vehicleId==v.id)emp+=num(x.amount)}for(i=0;i<db.partnerWorks.length;i++){x=db.partnerWorks[i];if(x.vehicleId==v.id){pCost+=num(x.cost);pCharge+=num(x.charge)}}for(i=0;i<db.partnerPayments.length;i++){x=db.partnerPayments[i];if(x.vehicleId==v.id)pPaid+=num(x.amount)}for(i=0;i<db.receipts.length;i++){x=db.receipts[i];if(x.vehicleId==v.id){rec+=num(x.amount);if(x.method!='چک'||x.checkStatus=='وصول شد')real+=num(x.amount);if(x.method=='چک'&&x.checkStatus=='در انتظار')pcheck+=num(x.amount)}}var final=Math.max(0,partCharge+pCharge+num(v.labor)+num(v.extra)-num(v.discount));return{partsCost:partBuy,partsCharge:partCharge,supplierPaid:supPaid,supplierDebt:partBuy-supPaid,partnerCost:pCost,partnerCharge:pCharge,partnerPaid:pPaid,partnerDebt:pCost-pPaid,empShare:emp,final:final,received:rec+direct,customerDirect:direct,realCash:real,pendingChecks:pcheck,balance:final-(rec+direct),profit:final-partBuy-pCost-emp}}
function employeeSalaryModeLabel(m){return m||'موردی/دستی'}
function employeeContractText(e){var m=e.salaryMode||'موردی/دستی',r=num(e.salaryRate);if(m=='درصدی از اجرت خودرو')return faDigits(r)+'٪ از اجرت خودرو';if(m=='روزانه')return money(r)+' / روز';if(m=='هفتگی')return money(r)+' / هفته';if(m=='ماهانه')return money(r)+' / ماه';return r>0?money(r)+' / مورد':'موردی / دستی'}
function empStats(e){var w=0,p=0,i,x;for(i=0;i<db.employeeWorks.length;i++){x=db.employeeWorks[i];if(x.employeeId==e.id)w+=num(x.amount)}for(i=0;i<db.employeePayments.length;i++){x=db.employeePayments[i];if(x.employeeId==e.id)p+=num(x.amount)}return{work:w,paid:p,balance:w-p}}
function employeeMonthStats(e,m){var w=0,p=0,adv=0,cars={},carCount=0,i,x;for(i=0;i<db.employeeWorks.length;i++){x=db.employeeWorks[i];if(x.employeeId==e.id&&monthOf(x.date)==m){w+=num(x.amount);if(x.vehicleId&&!cars[x.vehicleId]){cars[x.vehicleId]=1;carCount++}}}for(i=0;i<db.employeePayments.length;i++){x=db.employeePayments[i];if(x.employeeId==e.id&&monthOf(x.date)==m){p+=num(x.amount);if(x.payType=='علی‌الحساب'||x.payType=='پول دستی'||x.payType=='مساعده')adv+=num(x.amount)}}return{earned:w,paid:p,balance:w-p,advance:adv,cars:carCount}}
function employeeName(id){var e=findById(db.employees,id);return e?esc(e.name):'—'}
function salaryModeHint(){var m=formVal('salaryMode'),h=E('salaryHint');if(!h)return;if(m=='درصدی از اجرت خودرو')h.innerHTML='نرخ قرارداد را به درصد وارد کنید؛ مثال: <b>30</b> یعنی ۳۰٪ از اجرت صافکاری هر خودرویی که برای این پرسنل ثبت می‌شود.';else if(m=='روزانه')h.innerHTML='نرخ قرارداد = مبلغ حقوق یک روز. در ثبت کارکرد، تعداد روزها را وارد می‌کنید.';else if(m=='هفتگی')h.innerHTML='نرخ قرارداد = مبلغ حقوق یک هفته. در ثبت کارکرد، تعداد هفته‌ها را وارد می‌کنید.';else if(m=='ماهانه')h.innerHTML='نرخ قرارداد = مبلغ حقوق یک ماه. برای هر ماه یک واحد کارکرد ثبت می‌شود.';else h.innerHTML='در حالت موردی، مبلغ هر کار را هنگام ثبت کارکرد وارد می‌کنید.'}
function employeeWorkCalc(){var e=findById(db.employees,formVal('employeeId')),a=findNamed('amount'),u=Math.max(1,num(formVal('units'))),v=findById(db.vehicles,formVal('vehicleId')),info=E('empCalcInfo'),amt=0;if(!e){if(info)info.innerHTML='پرسنل را انتخاب کنید.';return}if(e.salaryMode=='درصدی از اجرت خودرو'){if(!v){if(info)info.innerHTML='برای پرسنل درصدی، پرونده خودرو را انتخاب کنید.';return}amt=Math.round(num(v.labor)*num(e.salaryRate)/100);if(info)info.innerHTML='محاسبه: '+faDigits(e.salaryRate)+'٪ از اجرت '+money(v.labor)+' = <b>'+money(amt)+'</b>'}else if(e.salaryMode=='روزانه'||e.salaryMode=='هفتگی'||e.salaryMode=='ماهانه'){amt=Math.round(num(e.salaryRate)*u);if(info)info.innerHTML=employeeContractText(e)+' × '+faDigits(u)+' واحد = <b>'+money(amt)+'</b>'}else{if(info)info.innerHTML='مبلغ این کار را دستی وارد کنید.';return}if(a)a.value=amt}
function supplierStats(s){var b=0,p=0,i,x;for(i=0;i<db.parts.length;i++){x=db.parts[i];if(x.supplierId==s.id){b+=num(x.qty)*num(x.unitPrice);p+=num(x.paidInitial)+num(x.customerDirect)}}for(i=0;i<db.supplierPayments.length;i++){x=db.supplierPayments[i];if(x.supplierId==s.id)p+=num(x.amount)}return{buy:b,paid:p,balance:b-p}}function partnerStats(p){var w=0,pa=0,i,x;for(i=0;i<db.partnerWorks.length;i++){x=db.partnerWorks[i];if(x.partnerId==p.id)w+=num(x.cost)}for(i=0;i<db.partnerPayments.length;i++){x=db.partnerPayments[i];if(x.partnerId==p.id)pa+=num(x.amount)}return{work:w,paid:pa,balance:w-pa}}function accountFlows(a){var inc=0,out=0,i,x;for(i=0;i<db.receipts.length;i++){x=db.receipts[i];if(x.accountId==a.id&&(x.method!='چک'||x.checkStatus=='وصول شد'))inc+=num(x.amount)}for(i=0;i<db.parts.length;i++){x=db.parts[i];if(x.accountId==a.id)out+=num(x.paidInitial)}for(i=0;i<db.supplierPayments.length;i++){x=db.supplierPayments[i];if(x.accountId==a.id)out+=num(x.amount)}for(i=0;i<db.employeePayments.length;i++){x=db.employeePayments[i];if(x.accountId==a.id)out+=num(x.amount)}for(i=0;i<db.partnerPayments.length;i++){x=db.partnerPayments[i];if(x.accountId==a.id)out+=num(x.amount)}for(i=0;i<db.expenses.length;i++){x=db.expenses[i];if(x.accountId==a.id)out+=num(x.amount)}return{inflow:inc,outflow:out,balance:num(a.opening)+inc-out}}
function accountBalance(a){return accountFlows(a).balance}
