function openCal(name){calTarget=name;var el=findNamed(name),m=el?normDigits(el.value).match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/):null,t=todayJ();calY=m?parseInt(m[1],10):t[0];calM=m?parseInt(m[2],10):t[1];renderCal();E('calShade').style.display='block'}function closeCal(){E('calShade').style.display='none'}function calMove(d){calM+=d;if(calM<1){calM=12;calY--}if(calM>12){calM=1;calY++}renderCal()}function renderCal(){var names=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'],g=j2g(calY,calM,1),wd=(new Date(g[0],g[1]-1,g[2]).getDay()+1)%7,days=jDays(calY,calM),h='<table class="calTbl"><tr><th>ش</th><th>ی</th><th>د</th><th>س</th><th>چ</th><th>پ</th><th>ج</th></tr><tr>',i,d=1,t=todayJ();E('calTitle').innerText=names[calM-1]+' '+faDigits(calY);for(i=0;i<wd;i++)h+='<td></td>';for(i=wd;i<42;i++){if(d<=days){h+='<td class="calDay '+(t[0]==calY&&t[1]==calM&&t[2]==d?'calToday':'')+'" onclick="pickCal('+d+')">'+faDigits(d)+'</td>';d++}else h+='<td></td>';if((i+1)%7==0&&i<41)h+='</tr><tr>'}E('calBody').innerHTML=h+'</tr></table>'}function pickCal(d){var el=findNamed(calTarget);if(el)el.value=calY+'/'+pad2(calM)+'/'+pad2(d);closeCal()}function calTodayPick(){var t=todayJ();calY=t[0];calM=t[1];pickCal(t[2])}function dateField(label,name,value){return'<div class="fg"><label>'+label+'</label><div class="dateWrap"><input readonly="readonly" name="'+name+'" value="'+esc(value||'')+'" onclick="openCal(\''+name+'\')"/><input class="calBtn" type="button" value="انتخاب تاریخ" onclick="openCal(\''+name+'\')"/></div></div>'}
