function closeModal(){E('modalShade').style.display='none';E('modalBody').innerHTML='';E('modalFooter').innerHTML='';E('modalFooter').style.display='none'}function findNamed(n){var all=E('modalBody').getElementsByTagName('*'),i;for(i=0;i<all.length;i++)if(all[i].name==n)return all[i];all=document.getElementsByName(n);return all.length?all[0]:null}function formVal(n){var e=findNamed(n);return e?e.value:''}function inputField(l,n,v,t,p,w){return'<div class="fg '+(w?'fgFull':'')+'"><label>'+l+'</label><input type="'+(t||'text')+'" name="'+n+'" value="'+esc(v||'')+'" placeholder="'+esc(p||'')+'"/></div>'}function areaField(l,n,v){return'<div class="fg fgFull"><label>'+l+'</label><textarea name="'+n+'">'+esc(v||'')+'</textarea></div>'}function selectField(l,n,o,v,chg){var h='<div class="fg"><label>'+l+'</label><select name="'+n+'" '+(chg?'onchange="'+chg+'"':'')+'>',i;for(i=0;i<o.length;i++)h+='<option '+(o[i]==v?'selected="selected"':'')+'>'+esc(o[i])+'</option>';return h+'</select></div>'}function tableWrap(hd,rows){if(!rows.length)return'<div class="empty">اطلاعاتی ثبت نشده است.</div>';var h='<div class="tableBox"><table><thead><tr>',i,j;for(i=0;i<hd.length;i++)h+='<th>'+hd[i]+'</th>';h+='</tr></thead><tbody>';for(i=0;i<rows.length;i++){h+='<tr>';for(j=0;j<rows[i].length;j++)h+='<td>'+rows[i][j]+'</td>';h+='</tr>'}return h+'</tbody></table></div>'}function kpi(t,v,c){return'<div class="col4"><div class="card"><div class="kpiTitle">'+t+'</div><div class="kpiValue '+(c||'')+'">'+v+'</div></div></div>'}function linesHtml(s){var a=String(s||'').split(/\r?\n/),h='<ul class="lineList">',i;for(i=0;i<a.length;i++)if(trimS(a[i]))h+='<li>'+esc(trimS(a[i]))+'</li>';return h+'</ul>'}
