function saveVehicle(id){var v=id?findById(db.vehicles,id):{id:idv('v'),code:uid('PDR')};v.customer=trimS(formVal('customer'));v.phone=trimS(normDigits(formVal('phone')));v.p2=trimS(normDigits(formVal('p2'))).replace(/\D/g,'').substr(0,2);v.pLetter=formVal('pLetter');v.p3=trimS(normDigits(formVal('p3'))).replace(/\D/g,'').substr(0,3);v.pIran=trimS(normDigits(formVal('pIran'))).replace(/\D/g,'').substr(0,2);v.plate=buildPlate();v.car=trimS(formVal('car'));v.entryDate=trimS(normDigits(formVal('entryDate')));v.estimate=num(formVal('estimate'));v.labor=num(formVal('labor'));v.discount=num(formVal('discount'));v.extra=num(formVal('extra'));v.status=formVal('status');v.deliveryDate=trimS(normDigits(formVal('deliveryDate')));v.job=trimS(formVal('job'));v.notes=trimS(formVal('notes'));v.insuranceEnabled=formVal('insuranceEnabled');v.insuranceCompany=trimS(formVal('insuranceCompany'));v.insuranceNumber=trimS(formVal('insuranceNumber'));v.insuranceAmount=num(formVal('insuranceAmount'));v.insuranceNote=trimS(formVal('insuranceNote'));if(!v.customer||!v.car){alert('نام مشتری و خودرو را وارد کنید.');return}if(v.p2.length!=2||v.p3.length!=3||v.pIran.length!=2){alert('پلاک را کامل وارد کنید: دو رقم، حرف، سه رقم، ایران دو رقم.');return}if(!v.entryDate){alert('تاریخ ورود را از تقویم انتخاب کنید.');return}if(!id)db.vehicles.unshift(v);for(var wi=0;wi<db.employeeWorks.length;wi++){var ew=db.employeeWorks[wi];if(ew.vehicleId==v.id&&ew.modeSnapshot=='درصدی از اجرت خودرو'){ew.baseLabor=num(v.labor);ew.amount=Math.round(num(v.labor)*num(ew.rateSnapshot)/100)}}if(saveDB(true)){closeModal();renderAll();showVehiclesPage()}}
function deleteVehicle(id){if(!confirm('پرونده خودرو و اطلاعات وابسته حذف شود؟'))return;removeById(db.vehicles,id);var sets=['parts','receipts','employeeWorks','supplierPayments','partnerWorks','partnerPayments'],i,j,a;for(i=0;i<sets.length;i++){a=db[sets[i]];for(j=a.length-1;j>=0;j--)if(a[j].vehicleId==id)a.splice(j,1)}saveDB()}
function vehicleRelated(v){var s=vehicleStats(v),ir=[],legacy=[],er=[],wr=[],rr=[],i,x,e,inv,it,total,paid;for(i=0;i<db.purchaseInvoices.length;i++){inv=db.purchaseInvoices[i];if(inv.vehicleId==v.id){it=purchaseInvoiceItems(inv.id);total=purchaseInvoiceTotal(inv.id);paid=purchaseInvoicePaid(inv);ir.push([esc(inv.date),supplierName(inv.supplierId),esc(inv.invoiceNo||'—'),faDigits(it.length),money(total),money(paid),'<b class="'+(total-paid>0?'kpiDanger':'kpiOk')+'">'+money(total-paid)+'</b>','<button class="btn btnSmall btnLight" onclick="purchaseInvoiceModal(\''+inv.id+'\',\''+v.id+'\')">ویرایش</button> <button class="btn btnSmall btnDanger" onclick="deletePurchaseInvoice(\''+inv.id+'\',\''+v.id+'\')">حذف</button>'])}}for(i=0;i<db.parts.length;i++){x=db.parts[i];if(x.vehicleId==v.id&&!x.invoiceId)legacy.push([esc(x.item),supplierName(x.supplierId),faDigits(x.qty),money(num(x.qty)*num(x.unitPrice)),money(num(x.qty)*num(x.sellUnitPrice)), '<button class="btn btnSmall btnLight" onclick="partModal(\''+x.id+'\',\''+v.id+'\')">ویرایش</button>'])}for(i=0;i<db.employeeWorks.length;i++){x=db.employeeWorks[i];if(x.vehicleId==v.id){e=findById(db.employees,x.employeeId);er.push([e?esc(e.name):'—',esc(x.modeSnapshot||''),faDigits(x.units||1),money(x.amount),esc(x.date),'<button class="btn btnSmall btnLight" onclick="empWorkModal(\''+x.id+'\',\''+x.employeeId+'\',\''+v.id+'\')">ویرایش</button> <button class="btn btnSmall btnDanger" onclick="deleteChild(\'employeeWorks\',\''+x.id+'\',\''+v.id+'\')">حذف</button>'])}}for(i=0;i<db.partnerWorks.length;i++){x=db.partnerWorks[i];if(x.vehicleId==v.id)wr.push([partnerName(x.partnerId),esc(x.desc),money(x.cost),money(x.charge),'<button class="btn btnSmall btnLight" onclick="partnerWorkModal(\''+x.id+'\',\''+v.id+'\')">ویرایش</button> <button class="btn btnSmall btnDanger" onclick="deleteChild(\'partnerWorks\',\''+x.id+'\',\''+v.id+'\')">حذف</button>'])}for(i=0;i<db.receipts.length;i++){x=db.receipts[i];if(x.vehicleId==v.id)rr.push([esc(x.date),esc(x.method),money(x.amount),x.method=='چک'?badge(x.checkStatus):'—','<button class="btn btnSmall btnLight" onclick="receiptModal(\''+v.id+'\',\''+x.id+'\')">ویرایش</button> <button class="btn btnSmall btnDanger" onclick="deleteChild(\'receipts\',\''+x.id+'\',\''+v.id+'\')">حذف</button>'])}var ph='<div class="subHead">خلاصه مالی پرونده</div><div class="row">'+kpi('برآورد اولیه',money(v.estimate))+kpi('مبلغ نهایی فعلی',money(s.final))+kpi('دریافتی مشتری',money(s.received))+kpi('مانده مشتری',money(s.balance),s.balance>0?'kpiDanger':'kpiOk')+'</div><div class="clear"></div><div class="subHead">فاکتورهای لوازم</div><button class="btn btnGold btnSmall" onclick="purchaseInvoiceModal(\'\',\''+v.id+'\')">+ ثبت فاکتور لوازم</button><div style="margin-top:6px">'+tableWrap(['تاریخ','فروشنده','شماره','اقلام','جمع خرید','پرداخت اولیه','مانده اولیه','عملیات'],ir)+'</div>';if(legacy.length)ph+='<div class="notice" style="margin-top:8px">اقلام تکی ثبت‌شده در نسخه‌های قبلی:</div>'+tableWrap(['قطعه','فروشنده','تعداد','هزینه خرید','مبلغ مشتری','عملیات'],legacy);ph+='<div class="subHead">کارکنان مجموعه روی این خودرو</div><button class="btn btnGold btnSmall" onclick="empWorkModal(\'\',\'\',\''+v.id+'\')">+ ثبت کارکرد پرسنل</button><div style="margin-top:6px">'+tableWrap(['پرسنل','مدل حقوق','واحد','سهم/حقوق','تاریخ','عملیات'],er)+'</div><div class="subHead">خدمات همکاران بیرونی (نقاش، جلوبندی و ...)</div><button class="btn btnGold btnSmall" onclick="partnerWorkModal(\'\',\''+v.id+'\')">+ افزودن خدمت همکار</button><div style="margin-top:6px">'+tableWrap(['همکار','شرح','هزینه شما','مبلغ مشتری','عملیات'],wr)+'</div><div class="subHead">دریافت‌های مشتری</div><button class="btn btnGold btnSmall" onclick="receiptModal(\''+v.id+'\',\'\')">+ ثبت دریافت</button><div style="margin-top:6px">'+tableWrap(['تاریخ','روش','مبلغ','چک','عملیات'],rr)+'</div><div class="invoiceTools"><button class="btn btnGold" onclick="printInvoice(\''+v.id+'\')">چاپ فاکتور</button><button class="btn" onclick="exportInvoiceJpg(\''+v.id+'\')">خروجی JPG</button></div>';return ph}
function deleteChild(set,id,v){if(!confirm('این مورد حذف شود؟'))return;removeById(db[set],id);saveDB(true);renderAll();vehicleModal(v)}

var purchaseLineSeq=0;
function purchaseInvoiceTotal(id){var t=0,i,x;for(i=0;i<db.parts.length;i++){x=db.parts[i];if(x.invoiceId==id)t+=num(x.qty)*num(x.unitPrice)}return t}
function purchaseInvoiceItems(id){var a=[],i,x;for(i=0;i<db.parts.length;i++){x=db.parts[i];if(x.invoiceId==id)a.push(x)}return a}
function purchaseInvoicePaid(inv){var t=0,i,x;for(i=0;i<db.parts.length;i++){x=db.parts[i];if(x.invoiceId==inv.id)t+=num(x.paidInitial)+num(x.customerDirect)}return t}
function purchaseLineHtml(ix,x){x=x||{item:'',qty:1,unitPrice:0,sellUnitPrice:0};var known=false,i;for(i=0;i<db.commonParts.length;i++)if(db.commonParts[i]==x.item)known=true;return'<div class="invoiceLine" id="purchaseLine_'+ix+'"><div><label>قطعه</label><select name="pi_common_'+ix+'">'+commonPartOptions(known?x.item:'')+'</select></div><div><label>یا مورد جدید</label><input name="pi_new_'+ix+'" value="'+esc(known?'':x.item)+'" placeholder="نام قطعه جدید"/></div><div class="narrow"><label>تعداد</label><input inputmode="decimal" name="pi_qty_'+ix+'" value="'+esc(x.qty||1)+'"/></div><div><label>قیمت خرید واحد</label><input inputmode="decimal" name="pi_buy_'+ix+'" value="'+esc(x.unitPrice||0)+'"/></div><div><label>قیمت برای مشتری</label><input inputmode="decimal" name="pi_sell_'+ix+'" value="'+esc(x.sellUnitPrice||x.unitPrice||0)+'"/></div><div class="del"><button class="btn btnDanger btnSmall" onclick="removePurchaseLine('+ix+')">حذف</button></div></div>'}
function addPurchaseLine(x){purchaseLineSeq++;var d=document.createElement('div');d.innerHTML=purchaseLineHtml(purchaseLineSeq,x);E('purchaseLines').appendChild(d.firstChild)}
function removePurchaseLine(ix){var e=E('purchaseLine_'+ix);if(e&&e.parentNode)e.parentNode.removeChild(e)}
function purchaseInvoiceModal(id,vId){var inv=id?findById(db.purchaseInvoices,id):null;if(!inv)inv={id:'',vehicleId:vId,supplierId:'',date:'',invoiceNo:'',payMode:'مانده‌دار',paidAmount:0,accountId:'',note:''};var items=id?purchaseInvoiceItems(id):[];purchaseLineSeq=0;var h='<div class="notice">هر خرید از لوازم‌فروش را به شکل یک فاکتور کامل ثبت کنید. اقلام این فاکتور همزمان وارد حساب خودرو و حساب فروشنده می‌شوند.</div><div class="formGrid"><div class="fg"><label>پرونده خودرو</label><select name="vehicleId">'+vehicleOptions(inv.vehicleId)+'</select></div><div class="fg"><label>لوازم‌فروش</label><select name="supplierId">'+supplierOptions(inv.supplierId)+'</select></div>'+dateField('تاریخ فاکتور','date',inv.date)+inputField('شماره فاکتور (اختیاری)','invoiceNo',inv.invoiceNo)+selectField('نحوه حساب فاکتور','payMode',['مانده‌دار','تسویه کامل','پرداخت بخشی'],inv.payMode||'مانده‌دار','togglePurchasePay()')+'<div id="purchasePayBox" class="fg" style="display:'+(inv.payMode=='مانده‌دار'?'none':'inline-block')+'"><label>مبلغ پرداخت‌شده</label><input name="paidAmount" value="'+esc(inv.paidAmount||0)+'"/></div><div id="purchaseAccountBox" class="fg" style="display:'+(inv.payMode=='مانده‌دار'?'none':'inline-block')+'"><label>حساب پرداخت</label><select name="accountId">'+accountOptions(inv.accountId)+'</select></div></div><div class="subHead">اقلام فاکتور</div><div id="purchaseLines" class="invoiceBuilder"></div><button class="btn btnGold btnSmall" onclick="addPurchaseLine(null)">+ افزودن ردیف کالا</button>'+areaField('توضیحات فاکتور','note',inv.note)+'<div class="formActions"><button class="btn btnGold" onclick="savePurchaseInvoice(\''+id+'\',\''+vId+'\')">ذخیره فاکتور</button><button class="btn btnLight" onclick="'+(vId?'vehicleModal(\\\''+vId+'\\\')':'closeModal()')+'">بستن</button></div>';openModal(id?'ویرایش فاکتور لوازم':'فاکتور جدید لوازم',h);if(items.length){for(var i=0;i<items.length;i++)addPurchaseLine(items[i])}else addPurchaseLine(null)}
function togglePurchasePay(){var m=formVal('payMode'),show=m=='مانده‌دار'?'none':'inline-block';E('purchasePayBox').style.display=show;E('purchaseAccountBox').style.display=show}
function savePurchaseInvoice(id,back){var inv=id?findById(db.purchaseInvoices,id):{id:idv('pinv')},vId=formVal('vehicleId'),sid=formVal('supplierId'),date=normDigits(formVal('date')),mode=formVal('payMode'),rows=E('purchaseLines').getElementsByTagName('div'),items=[],i,row,ix,item,qty,buy,sell,total=0,newName,sel;for(i=0;i<rows.length;i++){row=rows[i];if(row.className!='invoiceLine')continue;ix=row.id.replace('purchaseLine_','');newName=trimS(formVal('pi_new_'+ix));sel=formVal('pi_common_'+ix);item=newName||(sel&&sel!='مورد جدید...'?sel:'');qty=num(formVal('pi_qty_'+ix));buy=num(formVal('pi_buy_'+ix));sell=num(formVal('pi_sell_'+ix))||buy;if(item&&qty>0){items.push({item:item,qty:qty,unitPrice:buy,sellUnitPrice:sell});total+=qty*buy}}if(!vId||!sid||!date){alert('پرونده خودرو، فروشنده و تاریخ فاکتور را وارد کنید.');return}if(!items.length){alert('حداقل یک قلم کالا به فاکتور اضافه کنید.');return}var paid=mode=='مانده‌دار'?0:num(formVal('paidAmount'));if(mode=='تسویه کامل')paid=total;if(paid>total)paid=total;if(paid>0&&!formVal('accountId')){alert('حساب پرداخت را انتخاب کنید.');return}if(id){for(i=db.parts.length-1;i>=0;i--)if(db.parts[i].invoiceId==id)db.parts.splice(i,1)}inv.vehicleId=vId;inv.supplierId=sid;inv.date=date;inv.invoiceNo=trimS(formVal('invoiceNo'));inv.payMode=mode;inv.paidAmount=paid;inv.accountId=formVal('accountId');inv.note=trimS(formVal('note'));if(!id)db.purchaseInvoices.unshift(inv);for(i=0;i<items.length;i++){item=items[i];if(db.commonParts.join('|').indexOf(item.item)<0)db.commonParts.push(item.item);db.parts.unshift({id:idv('p'),invoiceId:inv.id,vehicleId:vId,date:date,item:item.item,supplierId:sid,qty:item.qty,unitPrice:item.unitPrice,sellUnitPrice:item.sellUnitPrice,paidInitial:i==0?paid:0,customerDirect:0,accountId:i==0?inv.accountId:'',note:'فاکتور '+(inv.invoiceNo||'بدون شماره')})}closeModal();if(saveDB(true)){renderAll();if(back)vehicleModal(back)}}
function deletePurchaseInvoice(id,back){if(!confirm('فاکتور لوازم و تمام اقلام آن حذف شود؟'))return;for(var i=db.parts.length-1;i>=0;i--)if(db.parts[i].invoiceId==id)db.parts.splice(i,1);removeById(db.purchaseInvoices,id);if(saveDB(true)){renderAll();if(back)vehicleModal(back)}}
function commonPartOptions(sel){var h='<option value="">انتخاب قطعه رایج</option>',i,n;for(i=0;i<db.commonParts.length;i++){n=db.commonParts[i];h+='<option '+(n==sel?'selected="selected"':'')+'>'+esc(n)+'</option>'}h+='<option>مورد جدید...</option>';return h}function partModal(id,vId){var x=id?findById(db.parts,id):null;if(!x)x={vehicleId:vId,date:'',item:'',supplierId:'',qty:1,unitPrice:0,sellUnitPrice:0,paidInitial:0,customerDirect:0,accountId:'',note:''};var known=false,i;for(i=0;i<db.commonParts.length;i++)if(db.commonParts[i]==x.item)known=true;var h='<div class="formGrid"><div class="fg"><label>پرونده خودرو</label><select name="vehicleId">'+vehicleOptions(x.vehicleId)+'</select></div>'+dateField('تاریخ خرید','date',x.date)+'<div class="fg"><label>قطعه رایج</label><select name="commonItem" onchange="toggleNewPart()">'+commonPartOptions(known?x.item:'')+'</select></div><div id="newPartBox" class="fg" style="display:'+(known?'none':'inline-block')+'"><label>نام قطعه جدید</label><input name="newItem" value="'+esc(known?'':x.item)+'"/></div><div class="fg"><label>لوازم‌فروش</label><select name="supplierId">'+supplierOptions(x.supplierId)+'</select></div>'+inputField('تعداد','qty',x.qty)+inputField('قیمت خرید واحد','unitPrice',x.unitPrice)+inputField('قیمت واحد برای مشتری','sellUnitPrice',x.sellUnitPrice||x.unitPrice)+inputField('پرداخت اولیه مجموعه','paidInitial',x.paidInitial)+inputField('پرداخت مستقیم مشتری به فروشنده','customerDirect',x.customerDirect)+'<div class="fg"><label>حساب پرداخت</label><select name="accountId">'+accountOptions(x.accountId)+'</select></div>'+areaField('توضیح','note',x.note)+'</div><div class="formActions"><button class="btn btnGold" onclick="savePart(\''+id+'\',\''+vId+'\')">ذخیره</button><button class="btn btnLight" onclick="vehicleModal(\''+vId+'\')">برگشت به پرونده</button></div>';openModal(id?'ویرایش قطعه':'افزودن قطعه به پرونده',h)}function toggleNewPart(){E('newPartBox').style.display=formVal('commonItem')=='مورد جدید...'?'inline-block':'none'}function savePart(id,back){var item=formVal('commonItem');if(!item||item=='مورد جدید...')item=trimS(formVal('newItem'));var x=id?findById(db.parts,id):{id:idv('p')};x.vehicleId=formVal('vehicleId');x.date=normDigits(formVal('date'));x.item=item;x.supplierId=formVal('supplierId');x.qty=num(formVal('qty'));x.unitPrice=num(formVal('unitPrice'));x.sellUnitPrice=num(formVal('sellUnitPrice'))||x.unitPrice;x.paidInitial=num(formVal('paidInitial'));x.customerDirect=num(formVal('customerDirect'));x.accountId=formVal('accountId');x.note=trimS(formVal('note'));if(!x.vehicleId||!x.item||!x.supplierId){alert('پرونده، قطعه و لوازم‌فروش را انتخاب کنید.');return}if(db.commonParts.join('|').indexOf(x.item)<0)db.commonParts.push(x.item);if(!id)db.parts.unshift(x);saveDB(true);renderAll();vehicleModal(back||x.vehicleId)}
function partnerWorkModal(id,vId){var x=id?findById(db.partnerWorks,id):null;if(!x)x={vehicleId:vId,partnerId:'',date:'',desc:'',cost:0,charge:0};var h='<div class="formGrid"><div class="fg"><label>پرونده خودرو</label><select name="vehicleId">'+vehicleOptions(x.vehicleId)+'</select></div><div class="fg"><label>همکار</label><select name="partnerId">'+partnerOptions(x.partnerId)+'</select></div>'+dateField('تاریخ','date',x.date)+inputField('هزینه قابل پرداخت به همکار','cost',x.cost)+inputField('مبلغ محاسبه برای مشتری','charge',x.charge||x.cost)+areaField('شرح خدمت','desc',x.desc)+'</div><div class="formActions"><button class="btn btnGold" onclick="savePartnerWork(\''+id+'\',\''+vId+'\')">ذخیره</button><button class="btn btnLight" onclick="vehicleModal(\''+vId+'\')">برگشت به پرونده</button></div>';openModal(id?'ویرایش خدمت همکار':'افزودن خدمت همکار',h)}function savePartnerWork(id,back){var x=id?findById(db.partnerWorks,id):{id:idv('pw')};x.vehicleId=formVal('vehicleId');x.partnerId=formVal('partnerId');x.date=normDigits(formVal('date'));x.cost=num(formVal('cost'));x.charge=num(formVal('charge'))||x.cost;x.desc=trimS(formVal('desc'));if(!x.vehicleId||!x.partnerId||x.cost<=0){alert('پرونده، همکار و مبلغ را وارد کنید.');return}if(!id)db.partnerWorks.unshift(x);saveDB(true);renderAll();vehicleModal(back||x.vehicleId)}
function receiptModal(vId,id){var x=id?findById(db.receipts,id):null;if(!x)x={vehicleId:vId,date:'',method:'کارت',reason:'بیعانه',amount:0,accountId:'',bank:'',ref:'',dueDate:'',checkStatus:'در انتظار',transferTo:'',transferDate:'',note:''};var h='<div class="formGrid"><div class="fg"><label>پرونده خودرو</label><select name="vehicleId">'+vehicleOptions(x.vehicleId)+'</select></div>'+dateField('تاریخ دریافت','date',x.date)+selectField('روش دریافت','method',['نقد','کارت','انتقال بانکی','چک','سایر'],x.method,'toggleCheckFields()')+selectField('بابت','reason',['بیعانه','پرداخت مرحله‌ای','تسویه نهایی','سایر'],x.reason)+inputField('مبلغ','amount',x.amount)+'<div class="fg"><label>حساب دریافت</label><select name="accountId">'+accountOptions(x.accountId)+'</select></div><div id="checkFields" class="fgFull" style="display:'+(x.method=='چک'?'block':'none')+'"><div class="checkBox"><div class="formGrid">'+inputField('بانک چک','bank',x.bank)+inputField('شماره چک/صیاد','ref',x.ref)+dateField('تاریخ سررسید','dueDate',x.dueDate)+selectField('وضعیت چک','checkStatus',['در انتظار','وصول شد','واگذار شد','برگشت خورد','لغو شد'],x.checkStatus,'toggleTransfer()')+'<div id="transferBox" class="fgFull" style="display:'+(x.checkStatus=='واگذار شد'?'block':'none')+'"><div class="formGrid">'+inputField('واگذار شده به','transferTo',x.transferTo)+dateField('تاریخ واگذاری','transferDate',x.transferDate)+'</div></div></div></div></div>'+areaField('توضیح','note',x.note)+'</div><div class="formActions"><button class="btn btnGold" onclick="saveReceipt(\''+id+'\',\''+vId+'\')">ذخیره</button>'+(vId?'<button class="btn btnLight" onclick="vehicleModal(\''+vId+'\')">برگشت به پرونده</button>':'')+'</div>';openModal(id?'ویرایش دریافت':'ثبت دریافت مشتری',h)}function toggleCheckFields(){E('checkFields').style.display=formVal('method')=='چک'?'block':'none'}function toggleTransfer(){E('transferBox').style.display=formVal('checkStatus')=='واگذار شد'?'block':'none'}function saveReceipt(id,back){var x=id?findById(db.receipts,id):{id:idv('r')};x.vehicleId=formVal('vehicleId');x.date=normDigits(formVal('date'));x.method=formVal('method');x.reason=formVal('reason');x.amount=num(formVal('amount'));x.accountId=formVal('accountId');x.bank=trimS(formVal('bank'));x.ref=trimS(formVal('ref'));x.dueDate=normDigits(formVal('dueDate'));x.checkStatus=formVal('checkStatus');x.transferTo=trimS(formVal('transferTo'));x.transferDate=normDigits(formVal('transferDate'));x.note=trimS(formVal('note'));if(!x.vehicleId||x.amount<=0){alert('پرونده و مبلغ دریافت را وارد کنید.');return}if(x.method=='چک'){if(!x.ref||!x.dueDate){alert('شماره و تاریخ سررسید چک را وارد کنید.');return}if(x.checkStatus=='واگذار شد'&&!x.transferTo){alert('نام شخص/مجموعه‌ای که چک به او واگذار شده را وارد کنید.');return}}else{x.bank='';x.ref='';x.dueDate='';x.checkStatus='';x.transferTo='';x.transferDate=''}if(!id)db.receipts.unshift(x);saveDB(true);renderAll();if(back)vehicleModal(back);else closeModal()}
function renderChecks(){var rows=[],i,x,v,ds;for(i=0;i<db.receipts.length;i++){x=db.receipts[i];if(x.method!='چک')continue;v=findById(db.vehicles,x.vehicleId);ds=dueState(x.dueDate,x.checkStatus);rows.push([v?esc(v.customer):'—',v?plateHtml(v):'—',money(x.amount),esc(x.bank),esc(x.ref),esc(x.dueDate),'<select onchange="quickCheck(\''+x.id+'\',this.value)"><option '+(x.checkStatus=='در انتظار'?'selected':'')+'>در انتظار</option><option '+(x.checkStatus=='وصول شد'?'selected':'')+'>وصول شد</option><option '+(x.checkStatus=='واگذار شد'?'selected':'')+'>واگذار شد</option><option '+(x.checkStatus=='برگشت خورد'?'selected':'')+'>برگشت خورد</option><option '+(x.checkStatus=='لغو شد'?'selected':'')+'>لغو شد</option></select>',badge(ds),esc(x.transferTo||'—'),'<button class="btn btnSmall btnLight" onclick="receiptModal(\''+x.vehicleId+'\',\''+x.id+'\')">ویرایش</button> <button class="btn btnSmall btnDanger" onclick="deleteItem(\'receipts\',\''+x.id+'\')">حذف</button>'])}E('checks').innerHTML='<div class="notice">وضعیت چک را مستقیم از جدول تغییر دهید. برای واگذاری، گیرنده و تاریخ واگذاری را در ویرایش چک ثبت کنید.</div>'+tableWrap(['مشتری','پلاک','مبلغ','بانک','شماره','سررسید','وضعیت','هشدار','واگذار به','عملیات'],rows)}function quickCheck(id,val){var x=findById(db.receipts,id);if(!x)return;x.checkStatus=val;if(val=='واگذار شد'&&!x.transferTo){saveDB(true);renderAll();receiptModal(x.vehicleId,x.id);return}saveDB()}
function supplierModal(id){var x=id?findById(db.suppliers,id):{name:'',phone:'',address:'',note:''};var h='<div class="formGrid">'+inputField('نام فروشگاه/فروشنده','name',x.name)+inputField('تلفن','phone',x.phone)+inputField('آدرس','address',x.address,'text','',true)+areaField('توضیح','note',x.note)+'</div><div class="formActions"><button class="btn btnGold" onclick="saveSupplier(\''+id+'\')">ذخیره</button></div>';openModal(id?'ویرایش لوازم‌فروش':'ثبت لوازم‌فروش',h)}function saveSupplier(id){var x=id?findById(db.suppliers,id):{id:idv('su')};x.name=trimS(formVal('name'));x.phone=normDigits(formVal('phone'));x.address=trimS(formVal('address'));x.note=trimS(formVal('note'));if(!x.name){alert('نام فروشنده را وارد کنید.');return}if(!id)db.suppliers.unshift(x);closeModal();saveDB()}function deleteSupplier(id){var i;for(i=0;i<db.parts.length;i++)if(db.parts[i].supplierId==id){alert('این فروشنده در خریدهای ثبت‌شده استفاده شده و قابل حذف نیست. ابتدا رکوردهای مربوط را اصلاح کنید.');return}if(confirm('فروشنده حذف شود؟')){removeById(db.suppliers,id);saveDB()}}function renderSuppliers(){var rows=[],i,x,s;for(i=0;i<db.suppliers.length;i++){x=db.suppliers[i];s=supplierStats(x);rows.push([esc(x.name),esc(x.phone),esc(x.address),money(s.buy),money(s.paid),'<b class="kpiDanger">'+money(s.balance)+'</b>','<button class="btn btnSmall btnLight" onclick="supplierModal(\''+x.id+'\')">ویرایش</button> <button class="btn btnSmall" onclick="supplierPayModal(\''+x.id+'\')">پرداخت</button> <button class="btn btnSmall btnDanger" onclick="deleteSupplier(\''+x.id+'\')">حذف</button>'])}E('suppliers').innerHTML='<div class="sectionHead"><h2>لوازم‌فروشان</h2><div class="actions"><button class="btn btnGold" onclick="supplierModal(\'\')">+ فروشنده جدید</button></div></div>'+tableWrap(['نام','تلفن','آدرس','جمع خرید','پرداخت','مانده','عملیات'],rows)}function supplierPayModal(sid){var h='<div class="formGrid"><div class="fg"><label>فروشنده</label><select name="supplierId">'+supplierOptions(sid)+'</select></div><div class="fg"><label>پرونده مرتبط (اختیاری)</label><select name="vehicleId">'+vehicleOptions('')+'</select></div>'+dateField('تاریخ','date','')+inputField('مبلغ','amount','')+selectField('روش پرداخت','method',['نقد','کارت','انتقال بانکی','چک','سایر'],'کارت')+'<div class="fg"><label>حساب پرداخت</label><select name="accountId">'+accountOptions('')+'</select></div>'+areaField('توضیح','note','')+'</div><div class="formActions"><button class="btn btnGold" onclick="saveSupplierPay()">ثبت</button></div>';openModal('پرداخت به لوازم‌فروش',h)}function saveSupplierPay(){var x={id:idv('sp'),supplierId:formVal('supplierId'),vehicleId:formVal('vehicleId'),date:normDigits(formVal('date')),amount:num(formVal('amount')),method:formVal('method'),accountId:formVal('accountId'),note:trimS(formVal('note'))};if(!x.supplierId||x.amount<=0){alert('فروشنده و مبلغ را وارد کنید.');return}db.supplierPayments.unshift(x);closeModal();saveDB()}
function partnerModal(id){var x=id?findById(db.partners,id):{name:'',type:'نقاش',phone:'',address:'',note:''};var h='<div class="formGrid">'+inputField('نام همکار','name',x.name)+selectField('نوع همکاری','type',['نقاش','جلوبندی‌ساز','مکانیک','برقکار','شیشه‌کار','تودوزی','کارواش/دیتیلینگ','سایر'],x.type)+inputField('تلفن','phone',x.phone)+inputField('آدرس','address',x.address,'text','',true)+areaField('توضیح','note',x.note)+'</div><div class="formActions"><button class="btn btnGold" onclick="savePartner(\''+id+'\')">ذخیره</button></div>';openModal(id?'ویرایش همکار':'ثبت همکار',h)}function savePartner(id){var x=id?findById(db.partners,id):{id:idv('pa')};x.name=trimS(formVal('name'));x.type=formVal('type');x.phone=normDigits(formVal('phone'));x.address=trimS(formVal('address'));x.note=trimS(formVal('note'));if(!x.name){alert('نام همکار را وارد کنید.');return}if(!id)db.partners.unshift(x);closeModal();saveDB()}function deletePartner(id){var i;for(i=0;i<db.partnerWorks.length;i++)if(db.partnerWorks[i].partnerId==id){alert('این همکار سابقه کار ثبت‌شده دارد و قابل حذف نیست.');return}if(confirm('همکار حذف شود؟')){removeById(db.partners,id);saveDB()}}function renderPartners(){var r=[],i,x,s;for(i=0;i<db.partners.length;i++){x=db.partners[i];s=partnerStats(x);r.push([esc(x.name),esc(x.type),esc(x.phone),money(s.work),money(s.paid),'<b class="kpiDanger">'+money(s.balance)+'</b>','<button class="btn btnSmall btnLight" onclick="partnerModal(\''+x.id+'\')">ویرایش</button> <button class="btn btnSmall" onclick="partnerPayModal(\''+x.id+'\')">پرداخت</button> <button class="btn btnSmall btnDanger" onclick="deletePartner(\''+x.id+'\')">حذف</button>'])}E('partners').innerHTML='<div class="sectionHead"><h2>همکاران بیرونی</h2><div class="actions"><button class="btn btnGold" onclick="partnerModal(\'\')">+ همکار جدید</button></div></div>'+tableWrap(['نام','نوع','تلفن','جمع کار','پرداخت','مانده','عملیات'],r)}function partnerPayModal(pid){var h='<div class="formGrid"><div class="fg"><label>همکار</label><select name="partnerId">'+partnerOptions(pid)+'</select></div><div class="fg"><label>پرونده مرتبط (اختیاری)</label><select name="vehicleId">'+vehicleOptions('')+'</select></div>'+dateField('تاریخ','date','')+inputField('مبلغ','amount','')+selectField('روش','method',['نقد','کارت','انتقال بانکی','چک','سایر'],'کارت')+'<div class="fg"><label>حساب پرداخت</label><select name="accountId">'+accountOptions('')+'</select></div>'+areaField('توضیح','note','')+'</div><div class="formActions"><button class="btn btnGold" onclick="savePartnerPay()">ثبت</button></div>';openModal('پرداخت به همکار',h)}function savePartnerPay(){var x={id:idv('pp'),partnerId:formVal('partnerId'),vehicleId:formVal('vehicleId'),date:normDigits(formVal('date')),amount:num(formVal('amount')),method:formVal('method'),accountId:formVal('accountId'),note:trimS(formVal('note'))};if(!x.partnerId||x.amount<=0){alert('همکار و مبلغ را وارد کنید.');return}db.partnerPayments.unshift(x);closeModal();saveDB()}
function renderParts(){var r=[],i,inv,v,it,total,paid;for(i=0;i<db.purchaseInvoices.length;i++){inv=db.purchaseInvoices[i];v=findById(db.vehicles,inv.vehicleId);it=purchaseInvoiceItems(inv.id);total=purchaseInvoiceTotal(inv.id);paid=purchaseInvoicePaid(inv);r.push([esc(inv.date),v?esc(v.code)+' | '+esc(v.customer):'—',supplierName(inv.supplierId),esc(inv.invoiceNo||'—'),faDigits(it.length),money(total),money(paid),'<b class="'+(total-paid>0?'kpiDanger':'kpiOk')+'">'+money(total-paid)+'</b>','<button class="btn btnSmall btnLight" onclick="purchaseInvoiceModal(\''+inv.id+'\',\''+inv.vehicleId+'\')">ویرایش</button>'])}E('parts').innerHTML='<div class="notice">هر ردیف این جدول یک فاکتور کامل لوازم است. اقلام هر فاکتور داخل همان فاکتور ثبت می‌شوند و مانده فروشنده به‌صورت خودکار در حساب لوازم‌فروش دیده می‌شود.</div><div class="sectionHead"><h2>فاکتورهای خرید لوازم</h2><div class="actions"><button class="btn btnGold" onclick="purchaseInvoiceModal(\'\',\'\')">+ فاکتور جدید</button></div></div>'+tableWrap(['تاریخ','پرونده','فروشنده','شماره فاکتور','تعداد اقلام','جمع خرید','پرداخت اولیه','مانده اولیه','عملیات'],r)}function renderReceipts(){var r=[],i,x;for(i=0;i<db.receipts.length;i++){x=db.receipts[i];r.push([vehicleLabel(x.vehicleId),esc(x.date),esc(x.method),esc(x.reason),money(x.amount),accountName(x.accountId),x.method=='چک'?badge(x.checkStatus):'—','<button class="btn btnSmall btnLight" onclick="receiptModal(\''+x.vehicleId+'\',\''+x.id+'\')">ویرایش</button> <button class="btn btnSmall btnDanger" onclick="deleteItem(\'receipts\',\''+x.id+'\')">حذف</button>'])}E('receipts').innerHTML='<div class="notice">ورود اصلی دریافت‌ها از داخل پرونده خودرو انجام می‌شود.</div>'+tableWrap(['پرونده','تاریخ','روش','بابت','مبلغ','حساب','چک','عملیات'],r)}
function employeeModal(id){var x=id?findById(db.employees,id):{name:'',phone:'',type:'صافکار',salaryMode:'درصدی از اجرت خودرو',salaryRate:0,active:'بله'};var h='<div class="formGrid">'+inputField('نام و نام خانوادگی','name',x.name)+inputField('موبایل','phone',x.phone)+selectField('سمت / نوع همکاری','type',['شاگرد','صافکار','نقاش داخلی','مکانیک داخلی','مدیر','سایر'],x.type)+selectField('مدل حقوق','salaryMode',['درصدی از اجرت خودرو','روزانه','هفتگی','ماهانه','موردی/دستی'],x.salaryMode||'موردی/دستی','salaryModeHint()')+inputField('نرخ قرارداد (درصد یا مبلغ تومان)','salaryRate',x.salaryRate)+selectField('فعال است؟','active',['بله','خیر'],x.active||'بله')+'</div><div id="salaryHint" class="calcInfo"></div><div class="formActions"><button class="btn btnGold" onclick="saveEmployee(\''+id+'\')">ذخیره مشخصات</button><button class="btn btnLight" onclick="closeModal()">انصراف</button></div>';openModal(id?'ویرایش پرسنل':'ثبت پرسنل',h);salaryModeHint()}
function saveEmployee(id){var x=id?findById(db.employees,id):{id:idv('e'),code:uid('EMP')};x.name=trimS(formVal('name'));x.phone=normDigits(formVal('phone'));x.type=formVal('type');x.salaryMode=formVal('salaryMode');x.salaryRate=num(formVal('salaryRate'));x.active=formVal('active');x.settlement=x.salaryMode;if(!x.name){alert('نام پرسنل را وارد کنید.');return}if(x.salaryMode!='موردی/دستی'&&x.salaryRate<=0){alert('نرخ قرارداد را وارد کنید.');return}if(x.salaryMode=='درصدی از اجرت خودرو'&&(x.salaryRate<=0||x.salaryRate>100)){alert('درصد قرارداد باید بین 1 تا 100 باشد.');return}if(!id)db.employees.unshift(x);closeModal();saveDB()}
function renderEmployees(){var m=E('employeeMonth')?normDigits(E('employeeMonth').value):'';if(!m){var t=todayJ();m=t[0]+'/'+pad2(t[1])}var r=[],payRows=[],workRows=[],i,x,st,ms,e,v;for(i=0;i<db.employees.length;i++){x=db.employees[i];st=empStats(x);ms=employeeMonthStats(x,m);r.push([esc(x.code),esc(x.name),esc(x.type),employeeContractText(x),money(ms.earned),money(ms.paid),(ms.balance>0?'<span class="payrollPos">'+money(ms.balance)+'</span>':(ms.balance<0?'<span class="payrollNeg">علی‌الحساب '+money(-ms.balance)+'</span>':money(0))),money(st.balance),'<div class="employeeActions"><button class="btn btnSmall btnLight" onclick="employeeModal(\''+x.id+'\')">مشخصات</button><button class="btn btnSmall btnGold" onclick="empWorkModal(\'\',\''+x.id+'\',\'\')">+ کارکرد</button><button class="btn btnSmall" onclick="empPayModal(\'\',\''+x.id+'\')">+ واریزی</button><button class="btn btnSmall btnLight" onclick="employeeStatementModal(\''+x.id+'\',\''+m+'\')">ریز حساب</button><button class="btn btnSmall btnDanger" onclick="deleteEmployee(\''+x.id+'\')">حذف</button></div>'])}for(i=0;i<db.employeePayments.length;i++){x=db.employeePayments[i];if(monthOf(x.date)==m){e=findById(db.employees,x.employeeId);payRows.push([esc(x.date),e?esc(e.name):'—',esc(x.payType||'حقوق / تسویه'),money(x.amount),esc(x.method||''),accountName(x.accountId),esc(x.note||''),'<button class="btn btnSmall btnLight" onclick="empPayModal(\''+x.id+'\',\''+x.employeeId+'\')">ویرایش</button> <button class="btn btnSmall btnDanger" onclick="deleteItem(\'employeePayments\',\''+x.id+'\')">حذف</button>'])}}for(i=0;i<db.employeeWorks.length;i++){x=db.employeeWorks[i];if(monthOf(x.date)==m){e=findById(db.employees,x.employeeId);v=findById(db.vehicles,x.vehicleId);workRows.push([esc(x.date),e?esc(e.name):'—',v?esc(v.code)+' | '+esc(v.car):'حقوق ثابت / بدون خودرو',esc(x.modeSnapshot||''),faDigits(x.units||1),money(x.amount),esc(x.desc||''),'<button class="btn btnSmall btnLight" onclick="empWorkModal(\''+x.id+'\',\''+x.employeeId+'\',\''+(x.vehicleId||'')+'\')">ویرایش</button> <button class="btn btnSmall btnDanger" onclick="deleteItem(\'employeeWorks\',\''+x.id+'\')">حذف</button>'])}}E('employees').innerHTML='<div class="sectionHead"><h2>حقوق و حساب پرسنل</h2><div class="actions"><button class="btn btnLight" onclick="empWorkModal(\'\',\'\',\'\')">+ ثبت کارکرد / استحقاق</button><button class="btn btnLight" onclick="empPayModal(\'\',\'\')">+ ثبت واریزی / پول دستی</button><button class="btn btnGold" onclick="employeeModal(\'\')">+ پرسنل جدید</button></div></div><div class="notice">قاعده ساده: <b>کارکرد</b> یعنی مبلغی که پرسنل کسب کرده؛ <b>واریزی</b> یعنی پولی که واقعاً گرفته. علی‌الحساب و پول دستی فقط در واریزی ثبت می‌شوند.</div><div class="payrollBar"><label>ماه گزارش پرسنل (مثال 1405/07): </label><input class="monthInput" id="employeeMonth" value="'+esc(m)+'" onkeyup="renderEmployees()"/></div>'+tableWrap(['کد','نام','سمت','قرارداد','کارکرد ماه','دریافتی ماه','مانده ماه','مانده کل','عملیات'],r)+'<div class="subHead">واریزی‌های ماه '+esc(m)+'</div>'+tableWrap(['تاریخ','پرسنل','نوع واریزی','مبلغ','روش','حساب','توضیح','عملیات'],payRows)+'<div class="subHead">کارکرد / استحقاق ماه '+esc(m)+'</div>'+tableWrap(['تاریخ','پرسنل','مبنای کار','مدل','واحد','مبلغ','شرح','عملیات'],workRows)}
function empWorkModal(id,empId,vehicleId){var x=id?findById(db.employeeWorks,id):{employeeId:empId||'',vehicleId:vehicleId||'',date:'',units:1,amount:0,desc:'',modeSnapshot:'',rateSnapshot:0,baseLabor:0};var h='<div class="formGrid"><div class="fg"><label>پرسنل</label><select name="employeeId" onchange="employeeWorkCalc()">'+employeeOptions(x.employeeId)+'</select></div><div class="fg"><label>پرونده خودرو (برای درصدی الزامی)</label><select name="vehicleId" onchange="employeeWorkCalc()">'+vehicleOptions(x.vehicleId)+'</select></div>'+dateField('تاریخ کارکرد','date',x.date)+inputField('تعداد واحد (روز / هفته / ماه)','units',x.units||1)+inputField('مبلغ کارکرد','amount',x.amount)+areaField('شرح / توضیح کارکرد','desc',x.desc)+'</div><div id="empCalcInfo" class="calcInfo">برای محاسبه خودکار، پرسنل و در صورت درصدی بودن خودرو را انتخاب کنید.</div><div class="formActions"><button class="btn btnLight" onclick="employeeWorkCalc()">محاسبه مبلغ</button><button class="btn btnGold" onclick="saveEmpWork(\''+id+'\',\''+(vehicleId||x.vehicleId||'')+'\')">ذخیره کارکرد</button><button class="btn btnLight" onclick="closeModal()">انصراف</button></div>';openModal(id?'ویرایش کارکرد':'ثبت کارکرد / استحقاق پرسنل',h);if(!id)employeeWorkCalc()}
function saveEmpWork(id,backVehicle){var e=findById(db.employees,formVal('employeeId')),v=findById(db.vehicles,formVal('vehicleId')),x=id?findById(db.employeeWorks,id):{id:idv('ew')};if(!e){alert('پرسنل را انتخاب کنید.');return}x.employeeId=e.id;x.vehicleId=formVal('vehicleId');x.date=normDigits(formVal('date'));x.units=Math.max(1,num(formVal('units')));x.amount=num(formVal('amount'));x.desc=trimS(formVal('desc'));x.modeSnapshot=e.salaryMode;x.rateSnapshot=num(e.salaryRate);x.baseLabor=v?num(v.labor):0;if(!x.date){alert('تاریخ کارکرد را انتخاب کنید.');return}if(e.salaryMode=='درصدی از اجرت خودرو'&&!v){alert('برای پرسنل درصدی، پرونده خودرو الزامی است.');return}if(x.amount<=0){alert('مبلغ کارکرد باید بیشتر از صفر باشد.');return}if(!id)db.employeeWorks.unshift(x);if(saveDB(true)){closeModal();renderAll();if(backVehicle)vehicleModal(backVehicle)}}
function empPayModal(id,empId){var x=id?findById(db.employeePayments,id):{employeeId:empId||'',date:'',amount:0,payType:'حقوق / تسویه',method:'کارت',accountId:'',note:''};var h='<div class="formGrid"><div class="fg"><label>پرسنل</label><select name="employeeId">'+employeeOptions(x.employeeId)+'</select></div>'+dateField('تاریخ واریزی','date',x.date)+selectField('نوع واریزی','payType',['حقوق / تسویه','علی‌الحساب','پول دستی','مساعده','پاداش','سایر'],x.payType||'حقوق / تسویه')+inputField('مبلغ','amount',x.amount)+selectField('روش پرداخت','method',['نقد','کارت','انتقال بانکی','چک','سایر'],x.method||'کارت')+'<div class="fg"><label>حساب پرداخت</label><select name="accountId">'+accountOptions(x.accountId)+'</select></div>'+areaField('توضیح','note',x.note||'')+'</div><div class="notice">هر مبلغی که واقعاً به پرسنل می‌دهید — حتی پول دستی یا علی‌الحساب — از همین قسمت ثبت شود.</div><div class="formActions"><button class="btn btnGold" onclick="saveEmpPay(\''+id+'\')">ذخیره واریزی</button><button class="btn btnLight" onclick="closeModal()">انصراف</button></div>';openModal(id?'ویرایش واریزی پرسنل':'ثبت واریزی / علی‌الحساب',h)}
function saveEmpPay(id){var x=id?findById(db.employeePayments,id):{id:idv('ep')};x.employeeId=formVal('employeeId');x.date=normDigits(formVal('date'));x.payType=formVal('payType');x.amount=num(formVal('amount'));x.method=formVal('method');x.accountId=formVal('accountId');x.note=trimS(formVal('note'));if(!x.employeeId){alert('پرسنل را انتخاب کنید.');return}if(!x.date){alert('تاریخ واریزی را انتخاب کنید.');return}if(x.amount<=0){alert('مبلغ واریزی را وارد کنید.');return}if(!id)db.employeePayments.unshift(x);closeModal();saveDB()}
function employeeStatementModal(empId,m){var e=findById(db.employees,empId);if(!e)return;var ms=employeeMonthStats(e,m),st=empStats(e),wr=[],pr=[],i,x,v;for(i=0;i<db.employeeWorks.length;i++){x=db.employeeWorks[i];if(x.employeeId==empId&&monthOf(x.date)==m){v=findById(db.vehicles,x.vehicleId);wr.push([esc(x.date),v?esc(v.code)+' | '+esc(v.customer):'حقوق ثابت / بدون خودرو',esc(x.modeSnapshot||e.salaryMode),faDigits(x.units||1),money(x.amount),esc(x.desc||'')])}}for(i=0;i<db.employeePayments.length;i++){x=db.employeePayments[i];if(x.employeeId==empId&&monthOf(x.date)==m)pr.push([esc(x.date),esc(x.payType||''),money(x.amount),esc(x.method||''),accountName(x.accountId),esc(x.note||'')])}var bal=ms.balance>0?'طلب پرسنل: '+money(ms.balance):(ms.balance<0?'علی‌الحساب اضافه: '+money(-ms.balance):'تسویه ماه');openModal('ریز حساب '+e.name+' — '+m,'<div class="notice"><b>قرارداد:</b> '+employeeContractText(e)+'</div><div class="row">'+kpi('کارکرد ماه',money(ms.earned))+kpi('دریافتی ماه',money(ms.paid))+kpi('وضعیت ماه',bal)+kpi('مانده کل',money(st.balance))+'</div><div class="clear"></div><div class="subHead">کارکردهای این ماه</div>'+tableWrap(['تاریخ','خودرو / مبنا','مدل','واحد','مبلغ','شرح'],wr)+'<div class="subHead">واریزی‌های این ماه</div>'+tableWrap(['تاریخ','نوع','مبلغ','روش','حساب','توضیح'],pr)+'<div class="formActions"><button class="btn btnLight" onclick="closeModal()">بستن</button></div>')}
function deleteEmployee(id){if(!confirm('پرسنل و تمام سوابق کارکرد و واریزی او حذف شود؟'))return;removeById(db.employees,id);var i;for(i=db.employeeWorks.length-1;i>=0;i--)if(db.employeeWorks[i].employeeId==id)db.employeeWorks.splice(i,1);for(i=db.employeePayments.length-1;i>=0;i--)if(db.employeePayments[i].employeeId==id)db.employeePayments.splice(i,1);saveDB()}
function expenseModal(id){var x=id?findById(db.expenses,id):{date:'',category:'سایر',amount:0,method:'کارت',accountId:'',desc:''};var h='<div class="formGrid">'+dateField('تاریخ','date',x.date)+selectField('دسته هزینه','category',['اجاره','قبوض','صبحانه و پذیرایی','ابزار و تجهیزات','مواد مصرفی','تعمیر و نگهداری','حمل و نقل','سایر'],x.category)+inputField('مبلغ','amount',x.amount)+selectField('روش','method',['نقد','کارت','انتقال بانکی','چک','سایر'],x.method)+'<div class="fg"><label>حساب پرداخت</label><select name="accountId">'+accountOptions(x.accountId)+'</select></div>'+areaField('شرح','desc',x.desc)+'</div><div class="formActions"><button class="btn btnGold" onclick="saveExpense(\''+id+'\')">ذخیره</button></div>';openModal(id?'ویرایش هزینه':'ثبت هزینه',h)}function saveExpense(id){var x=id?findById(db.expenses,id):{id:idv('x')};x.date=normDigits(formVal('date'));x.category=formVal('category');x.amount=num(formVal('amount'));x.method=formVal('method');x.accountId=formVal('accountId');x.desc=trimS(formVal('desc'));if(x.amount<=0){alert('مبلغ را وارد کنید.');return}if(!id)db.expenses.unshift(x);closeModal();saveDB()}function renderExpenses(){var r=[],i,x;for(i=0;i<db.expenses.length;i++){x=db.expenses[i];r.push([esc(x.date),esc(x.category),esc(x.desc),money(x.amount),esc(x.method),accountName(x.accountId),'<button class="btn btnSmall btnLight" onclick="expenseModal(\''+x.id+'\')">ویرایش</button> <button class="btn btnSmall btnDanger" onclick="deleteItem(\'expenses\',\''+x.id+'\')">حذف</button>'])}E('expenses').innerHTML='<div class="sectionHead"><h2>هزینه‌های مجموعه</h2><div class="actions"><button class="btn btnGold" onclick="expenseModal(\'\')">+ هزینه جدید</button></div></div>'+tableWrap(['تاریخ','دسته','شرح','مبلغ','روش','حساب','عملیات'],r)}
function accountModal(id){var x=id?findById(db.accounts,id):{name:'',type:'حساب بانکی',opening:0};var h='<div class="formGrid">'+inputField('نام حساب','name',x.name)+selectField('نوع','type',['صندوق نقدی','حساب بانکی','کارتخوان','سایر'],x.type)+inputField('موجودی اول دوره','opening',x.opening)+'</div><div class="formActions"><button class="btn btnGold" onclick="saveAccount(\''+id+'\')">ذخیره</button><button class="btn btnLight" onclick="closeModal()">بستن</button></div>';openModal(id?'ویرایش حساب':'تعریف حساب',h)}function saveAccount(id){var x=id?findById(db.accounts,id):{id:idv('a')};x.name=trimS(formVal('name'));x.type=formVal('type');x.opening=num(formVal('opening'));if(!x.name){alert('نام حساب را وارد کنید.');return}if(!id)db.accounts.unshift(x);closeModal();saveDB()}function renderAccounts(){var r=[],i,x,f;for(i=0;i<db.accounts.length;i++){x=db.accounts[i];f=accountFlows(x);r.push([esc(x.name),esc(x.type),money(x.opening),money(f.inflow),money(f.outflow),'<b class="'+(f.balance<0?'kpiDanger':'kpiOk')+'">'+money(f.balance)+'</b>','<button class="btn btnSmall btnLight" onclick="accountModal(\''+x.id+'\')">ویرایش</button> <button class="btn btnSmall btnDanger" onclick="deleteAccount(\''+x.id+'\')">حذف</button>'])}E('accounts').innerHTML='<div class="accountExplain"><b>مانده محاسباتی یعنی چه؟</b><br/>موجودی اول دوره + دریافت‌های نقدی/کارت/انتقال و چک‌های وصول‌شده − تمام پرداخت‌های ثبت‌شده از همان حساب. این عدد موجودی بانکی واقعی را فقط وقتی دقیق نشان می‌دهد که همه دریافت‌ها و پرداخت‌ها را در برنامه ثبت کرده باشید.</div><div class="sectionHead"><h2>صندوق و حساب‌ها</h2><div class="actions"><button class="btn btnGold" onclick="accountModal(\'\')">+ حساب جدید</button></div></div>'+tableWrap(['نام','نوع','اول دوره','ورودی ثبت‌شده','خروجی ثبت‌شده','مانده محاسباتی','عملیات'],r)}function deleteAccount(id){if(confirm('حساب حذف شود؟')){removeById(db.accounts,id);saveDB()}}

function noteModal(id){var x=id?findById(db.notes,id):{title:'',person:'',phone:'',type:'طلب/حساب',amount:0,dueDate:'',status:'باز',text:'',createdDate:''};var h='<div class="formGrid">'+inputField('عنوان یادداشت','title',x.title)+inputField('نام شخص / مجموعه','person',x.person)+inputField('شماره تماس','phone',x.phone)+selectField('نوع','type',['طلب/حساب','وعده پرداخت','پیگیری','یادداشت عمومی','سایر'],x.type)+inputField('مبلغ (اختیاری)','amount',x.amount)+dateField('سررسید / تاریخ پیگیری','dueDate',x.dueDate)+selectField('وضعیت','status',['باز','انجام شد','لغو شد'],x.status)+areaField('متن یادداشت','text',x.text)+'</div><div class="formActions"><button class="btn btnGold" onclick="saveNote(\''+id+'\')">ذخیره یادداشت</button><button class="btn btnLight" onclick="closeModal()">بستن</button></div>';openModal(id?'ویرایش یادداشت':'یادداشت جدید',h)}
function saveNote(id){var x=id?findById(db.notes,id):{id:idv('n'),createdDate:todayJ()[0]+'/'+pad2(todayJ()[1])+'/'+pad2(todayJ()[2])};x.title=trimS(formVal('title'));x.person=trimS(formVal('person'));x.phone=trimS(normDigits(formVal('phone')));x.type=formVal('type');x.amount=num(formVal('amount'));x.dueDate=trimS(normDigits(formVal('dueDate')));x.status=formVal('status');x.text=trimS(formVal('text'));if(!x.title&&!x.text){alert('عنوان یا متن یادداشت را وارد کنید.');return}if(!id)db.notes.unshift(x);closeModal();saveDB()}
function deleteNote(id){if(confirm('این یادداشت حذف شود؟')){removeById(db.notes,id);saveDB()}}
function renderNotes(){var q=E('noteSearch')?trimS(E('noteSearch').value):'',h='<div class="sectionHead"><h2>یادداشت‌ها و پیگیری‌ها</h2><div class="actions"><button class="btn btnGold" onclick="noteModal(\'\')">+ یادداشت جدید</button></div></div><input id="noteSearch" class="searchBox" onkeyup="renderNotes()" value="'+esc(q)+'" placeholder="جستجو در عنوان، شخص یا متن"/><div style="margin-top:10px">',i,x,hay,shown=0;for(i=0;i<db.notes.length;i++){x=db.notes[i];hay=x.title+' '+x.person+' '+x.phone+' '+x.text;if(q&&hay.indexOf(q)<0)continue;shown++;h+='<div class="noteCard '+(x.status=='انجام شد'?'done':'')+'"><div class="noteTitle">'+esc(x.title||x.type)+'</div><div class="noteMeta">'+esc(x.type)+' | '+esc(x.person||'بدون نام')+(x.phone?' | '+esc(x.phone):'')+(num(x.amount)>0?' | مبلغ: '+money(x.amount):'')+(x.dueDate?' | پیگیری: '+esc(x.dueDate):'')+' | '+badge(x.status)+'</div><div class="noteText">'+esc(x.text||'—')+'</div><div style="margin-top:8px"><button class="btn btnSmall btnLight" onclick="noteModal(\''+x.id+'\')">ویرایش</button> <button class="btn btnSmall btnDanger" onclick="deleteNote(\''+x.id+'\')">حذف</button></div></div>'}if(!shown)h+='<div class="empty">یادداشتی ثبت نشده است.</div>';h+='</div>';E('notes').innerHTML=h}
function renderMonthly(){var m=E('monthFilter')?normDigits(E('monthFilter').value):'';if(!m){var t=todayJ();m=t[0]+'/'+pad2(t[1])}var vehicles=0,invoice=0,gross=0,discount=0,real=0,pending=0,partsBuy=0,supPaid=0,partnerPaid=0,empPaid=0,empEarned=0,empUnlinked=0,exp=0,i,x,st;for(i=0;i<db.vehicles.length;i++){x=db.vehicles[i];if(monthOf(x.entryDate)==m){vehicles++;st=vehicleStats(x);invoice+=st.final;gross+=st.profit;discount+=num(x.discount)}}for(i=0;i<db.receipts.length;i++){x=db.receipts[i];if(monthOf(x.date)==m){if(x.method!='چک'||x.checkStatus=='وصول شد')real+=num(x.amount);if(x.method=='چک'&&x.checkStatus=='در انتظار')pending+=num(x.amount)}}for(i=0;i<db.parts.length;i++){x=db.parts[i];if(monthOf(x.date)==m){partsBuy+=num(x.qty)*num(x.unitPrice);supPaid+=num(x.paidInitial)}}for(i=0;i<db.supplierPayments.length;i++){x=db.supplierPayments[i];if(monthOf(x.date)==m)supPaid+=num(x.amount)}for(i=0;i<db.partnerPayments.length;i++){x=db.partnerPayments[i];if(monthOf(x.date)==m)partnerPaid+=num(x.amount)}for(i=0;i<db.employeePayments.length;i++){x=db.employeePayments[i];if(monthOf(x.date)==m)empPaid+=num(x.amount)}for(i=0;i<db.employeeWorks.length;i++){x=db.employeeWorks[i];if(monthOf(x.date)==m){empEarned+=num(x.amount);if(!x.vehicleId)empUnlinked+=num(x.amount)}}for(i=0;i<db.expenses.length;i++){x=db.expenses[i];if(monthOf(x.date)==m)exp+=num(x.amount)}var net=gross-exp-empUnlinked;E('monthly').innerHTML='<div class="sectionHead"><h2>گزارش ماهانه</h2></div><div class="card" style="margin-bottom:10px"><label>ماه گزارش (مثال 1405/07)</label><input id="monthFilter" class="searchBox" value="'+esc(m)+'" onkeyup="renderMonthly()"/></div><div class="row">'+kpi('خودروهای ورودی',faDigits(vehicles))+kpi('جمع فاکتور',money(invoice))+kpi('وصول نقدی واقعی',money(real),'kpiOk')+kpi('چک در انتظار',money(pending),'kpiDanger')+kpi('خرید لوازم',money(partsBuy))+kpi('پرداخت فروشندگان',money(supPaid))+kpi('پرداخت همکاران',money(partnerPaid))+kpi('حقوق کسب‌شده پرسنل',money(empEarned))+kpi('پرداخت به کارکنان',money(empPaid))+kpi('هزینه‌های جاری',money(exp))+kpi('تخفیف',money(discount))+kpi('سود تقریبی',money(gross),'kpiOk')+kpi('سود خالص تقریبی',money(net),net>=0?'kpiOk':'kpiDanger')+'</div><div class="clear"></div><div class="notice">حقوق پرسنل بر اساس «کارکرد/استحقاق» محاسبه می‌شود؛ پرداختی و علی‌الحساب فقط جریان نقد را نشان می‌دهد. حقوق را دوباره در هزینه‌های عمومی ثبت نکنید.</div>'}
function renderSettlement(){var sel=E('settleVehicle')?E('settleVehicle').value:'';var h='<div class="card"><label>پرونده خودرو</label><select id="settleVehicle" class="searchBox" onchange="renderSettlement()">'+vehicleOptions(sel)+'</select></div>';if(sel){var v=findById(db.vehicles,sel),s=vehicleStats(v);h+='<div class="sectionHead"><h2>'+esc(v.customer)+' — '+plateText(v)+'</h2><div class="actions"><button class="btn btnLight" onclick="receiptModal(\''+v.id+'\',\'\')">ثبت پرداخت</button><button class="btn btnGold" onclick="printInvoice(\''+v.id+'\')">چاپ فاکتور</button><button class="btn" onclick="exportInvoiceJpg(\''+v.id+'\')">JPG</button></div></div><div class="row">'+kpi('لوازم برای مشتری',money(s.partsCharge))+kpi('اجرت',money(v.labor))+kpi('خدمات همکاران',money(s.partnerCharge))+kpi('مبلغ نهایی',money(s.final))+kpi('پرداخت مشتری',money(s.received))+kpi('چک در انتظار',money(s.pendingChecks))+kpi('بدهی لوازم‌فروش',money(s.supplierDebt))+kpi('بدهی همکاران',money(s.partnerDebt))+kpi('سود تقریبی',money(s.profit),'kpiOk')+'</div><div class="clear"></div><div class="card"><div class="kpiTitle">مبلغ قابل دریافت</div><div class="moneyBig '+(s.balance<=0?'moneyOk':'')+'">'+money(Math.max(0,s.balance))+'</div>'+badge(s.balance<=0?'تسویه شده':'مانده دارد')+'</div>';if(v.insuranceEnabled=='بله')h+='<div class="notice" style="margin-top:8px">بیمه: '+esc(v.insuranceCompany)+' | مبلغ اعلامی: <b>'+money(v.insuranceAmount)+'</b> | اختلاف با فاکتور واقعی: '+money(num(v.insuranceAmount)-s.final)+'</div>'}else h+='<div class="empty" style="margin-top:10px">یک پرونده خودرو را انتخاب کنید.</div>';E('settlement').innerHTML=h}
function invoiceItems(v){var a=[],i,x;if(num(v.labor)>0)a.push({d:'اجرت صافکاری و PDR',q:1,u:num(v.labor),t:num(v.labor)});for(i=0;i<db.parts.length;i++){x=db.parts[i];if(x.vehicleId==v.id)a.push({d:x.item,q:num(x.qty),u:num(x.sellUnitPrice),t:num(x.qty)*num(x.sellUnitPrice)})}for(i=0;i<db.partnerWorks.length;i++){x=db.partnerWorks[i];if(x.vehicleId==v.id)a.push({d:(partnerName(x.partnerId).replace(/&[^;]+;/g,'')+' - '+x.desc),q:1,u:num(x.charge),t:num(x.charge)})}if(num(v.extra)>0)a.push({d:'هزینه اضافه',q:1,u:num(v.extra),t:num(v.extra)});if(num(v.discount)>0)a.push({d:'تخفیف',q:1,u:-num(v.discount),t:-num(v.discount)});return a}function invoiceHtml(v){var s=vehicleStats(v),it=invoiceItems(v),i,rows='',date=v.deliveryDate||v.entryDate,inv='INV-'+v.code.replace('PDR-',''),jobs=linesHtml(v.job);for(i=0;i<it.length;i++)rows+='<tr><td>'+(i+1)+'</td><td>'+esc(it[i].d)+'</td><td>'+faDigits(it[i].q)+'</td><td>'+money(it[i].u)+'</td><td>'+money(it[i].t)+'</td></tr>';return'<div class="invoicePage"><div class="invHead"><div style="text-align:center;margin-bottom:8px"><img src="'+LOGO+'" style="max-width:240px;max-height:150px;width:auto;height:auto;display:inline-block"/></div><h1>'+esc(db.settings.workshop)+'</h1><div>'+esc(db.settings.address)+'</div><div>شماره تماس: '+esc(db.settings.phone)+'</div><div class="clear"></div></div><table class="invInfo"><tr><td><b>صورتحساب:</b> '+esc(inv)+'</td><td><b>تاریخ:</b> '+esc(date)+'</td></tr><tr><td><b>خریدار:</b> '+esc(v.customer)+'</td><td><b>شماره تماس:</b> '+esc(v.phone)+'</td></tr><tr><td><b>خودرو:</b> '+esc(v.car)+'</td><td><b>پلاک:</b> '+plateText(v)+'</td></tr><tr><td colspan="2"><b>شرح کار:</b> '+jobs+'</td></tr></table><table class="invTable"><tr><th>ردیف</th><th>شرح کالا یا خدمات</th><th>تعداد</th><th>قیمت واحد</th><th>قیمت کل</th></tr>'+rows+'</table><table class="invTotal"><tr><td><b>جمع کل:</b> '+money(s.final)+'</td><td><b>پرداخت شده:</b> '+money(s.received)+'</td><td><b>مانده:</b> '+money(Math.max(0,s.balance))+'</td></tr></table><div class="invFoot"><div style="float:right">امضای خریدار: ................................</div><div style="float:left">مهر و امضای فروشنده: ................................</div><div class="clear"></div></div></div>'}function printInvoice(id){var v=findById(db.vehicles,id);if(!v)return;E('printArea').innerHTML=invoiceHtml(v);window.print()}
function renderAlerts(){var q=E('globalSearch')?normDigits(E('globalSearch').value):'',r=[],i,v,s,x,over=0,near=0,ret=0;for(i=0;i<db.vehicles.length;i++){v=db.vehicles[i];if(!q||normDigits(v.code+' '+v.customer+' '+v.phone+' '+platePlain(v)+' '+v.car).indexOf(q)>=0){s=vehicleStats(v);r.push([esc(v.code),esc(v.customer),esc(v.phone),plateHtml(v),esc(v.car),money(s.balance),badge(v.status),'<button class="btn btnSmall btnGold" onclick="vehicleModal(\''+v.id+'\')">پرونده</button>'])}}for(i=0;i<db.receipts.length;i++){x=db.receipts[i];if(x.method=='چک'){var d=dueState(x.dueDate,x.checkStatus);if(d=='سررسید گذشته')over++;if(d=='نزدیک سررسید')near++;if(x.checkStatus=='برگشت خورد')ret++}}E('alerts').innerHTML='<div class="row">'+kpi('چک سررسید گذشته',faDigits(over),over?'kpiDanger':'')+kpi('چک نزدیک سررسید',faDigits(near))+kpi('چک برگشتی',faDigits(ret),ret?'kpiDanger':'')+'</div><div class="clear"></div><div class="sectionHead"><h2>جستجوی سریع</h2></div><input class="searchBox" id="globalSearch" onkeyup="renderAlerts()" value="'+esc(q)+'" placeholder="کد، نام، موبایل، پلاک یا خودرو"/><div style="margin-top:9px">'+tableWrap(['کد','مشتری','موبایل','پلاک','خودرو','مانده','وضعیت','عملیات'],r)+'</div>'}
function deleteItem(set,id){if(confirm('این رکورد حذف شود؟')){removeById(db[set],id);saveDB()}}
function renderAll(){renderDashboard();renderVehicles();renderChecks();renderSuppliers();renderPartners();renderParts();renderReceipts();renderEmployees();renderExpenses();renderAccounts();renderNotes();renderMonthly();renderSettlement();renderAlerts();renderSettings();renderBackup()}